class Solution:
    def findMin(self, nums: list[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:  # viz:compare
                lo = mid + 1  # viz:right
            else:
                hi = mid  # viz:left
        return nums[lo]  # viz:done
